def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    size = len(alphabet)
    index = {ch: i for i, ch in enumerate(alphabet)}

    children = [[-1] * size]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = index[ch]
            if children[state][c] == -1:
                children[state][c] = len(children)
                children.append([-1] * size)
                terminal.append(False)
            state = children[state][c]
        terminal[state] = True

    fail = [0] * len(children)
    queue = []

    for c in range(size):
        nxt = children[0][c]
        if nxt == -1:
            children[0][c] = 0
        else:
            queue.append(nxt)

    head = 0
    while head < len(queue):
        state = queue[head]
        head += 1
        terminal[state] |= terminal[fail[state]]

        for c in range(size):
            nxt = children[state][c]
            if nxt == -1:
                children[state][c] = children[fail[state]][c]
            else:
                fail[nxt] = children[fail[state]][c]
                queue.append(nxt)

    states = [state for state in range(len(children)) if not terminal[state]]
    position = {state: i for i, state in enumerate(states)}
    m = len(states)

    matrix = [[0] * m for _ in range(m)]
    for state in states:
        row = matrix[position[state]]
        for nxt in children[state]:
            if not terminal[nxt]:
                row[position[nxt]] += 1

    vector = [0] * m
    vector[position[0]] = 1

    while n:
        if n & 1:
            result = [0] * m
            for i, value in enumerate(vector):
                if value:
                    for j, count in enumerate(matrix[i]):
                        result[j] = (result[j] + value * count) % MOD
            vector = result

        n >>= 1
        if n:
            product = [[0] * m for _ in range(m)]
            for i in range(m):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, count in enumerate(matrix[k]):
                            product[i][j] = (product[i][j] + value * count) % MOD
            matrix = product

    return sum(vector) % MOD
